const decoder = new TextDecoder('ascii');

/**
 * Walks top-level atoms in an ArrayBuffer slice.
 * Yields { type, offset, size, payloadOffset, payloadSize }.
 *
 * size  — total atom size in bytes (header + payload)
 * type  — 4-char ASCII type string
 *
 * Per ISO/IEC 14496-12: size=1 means a 64-bit size in the next 8 bytes
 * (we don't expect those in dashcam files but handle them anyway).
 * size=0 means "atom runs to end of buffer".
 */
export function* walkAtoms(buffer, start = 0, end = buffer.byteLength) {
  const view = new DataView(buffer);
  let pos = start;
  while (pos + 8 <= end) {
    let size = view.getUint32(pos, false);
    const typeBytes = new Uint8Array(buffer, pos + 4, 4);
    const type = decoder.decode(typeBytes);
    let headerSize = 8;

    if (size === 1) {
      const hi = view.getUint32(pos + 8, false);
      const lo = view.getUint32(pos + 12, false);
      size = hi * 0x100000000 + lo;
      headerSize = 16;
    } else if (size === 0) {
      size = end - pos;
    }

    if (size < headerSize || pos + size > end) {
      // malformed — stop walking
      return;
    }

    yield {
      type,
      offset: pos,
      size,
      payloadOffset: pos + headerSize,
      payloadSize: size - headerSize,
    };

    pos += size;
  }
}

/**
 * Find the first occurrence of a 4-byte ASCII marker in a buffer slice.
 * Returns the offset (absolute, into `buffer`) or -1.
 *
 * Used by the Novatek parser to locate `GPS ` markers in mdat — the
 * Novatek format embeds GPS samples there outside the standard atom tree.
 */
export function findMarker(buffer, marker, start = 0, end = buffer.byteLength) {
  if (marker.length !== 4) throw new Error('marker must be 4 chars');
  const bytes = new Uint8Array(buffer);
  const m0 = marker.charCodeAt(0);
  const m1 = marker.charCodeAt(1);
  const m2 = marker.charCodeAt(2);
  const m3 = marker.charCodeAt(3);
  for (let i = start; i + 4 <= end; i++) {
    if (bytes[i] === m0 && bytes[i+1] === m1 && bytes[i+2] === m2 && bytes[i+3] === m3) {
      return i;
    }
  }
  return -1;
}

/**
 * Find ALL occurrences of a 4-byte ASCII marker. Returns an array of offsets.
 */
export function findAllMarkers(buffer, marker, start = 0, end = buffer.byteLength) {
  const offsets = [];
  let pos = start;
  while (pos < end) {
    const found = findMarker(buffer, marker, pos, end);
    if (found === -1) break;
    offsets.push(found);
    pos = found + 4;
  }
  return offsets;
}

const EPOCH_OFFSET_1904_TO_1970 = 2082844800; // seconds

/**
 * Parse the movie header (mvhd) inside the moov atom.
 * Returns { creationUtcMs, durationSeconds } or null if not found / malformed.
 *
 * Note on creationUtcMs: dashcam firmware varies. Some cameras write the
 * recording-start timestamp; others (Azdome M300S observed) write the
 * file-finalize timestamp, i.e. the recording end. Callers wanting the
 * recording-start instant should compare both `creationUtcMs` and
 * `creationUtcMs - durationSeconds*1000` against known reference times.
 */
export function parseMovieHeader(buffer) {
  let moov = null;
  for (const a of walkAtoms(buffer)) {
    if (a.type === 'moov') { moov = a; break; }
  }
  if (!moov) return null;

  let mvhd = null;
  for (const a of walkAtoms(buffer, moov.payloadOffset, moov.offset + moov.size)) {
    if (a.type === 'mvhd') { mvhd = a; break; }
  }
  if (!mvhd) return null;

  const view = new DataView(buffer);
  const off = mvhd.payloadOffset;
  const version = view.getUint8(off);
  // bytes off+1..off+3 are flags (ignored)

  let creation, timescale, duration;
  if (version === 1) {
    if (mvhd.payloadSize < 28) return null;
    const cHi = view.getUint32(off + 4, false);
    const cLo = view.getUint32(off + 8, false);
    creation = cHi * 0x100000000 + cLo;
    timescale = view.getUint32(off + 20, false);
    const dHi = view.getUint32(off + 24, false);
    const dLo = view.getUint32(off + 28, false);
    duration = dHi * 0x100000000 + dLo;
  } else {
    if (mvhd.payloadSize < 20) return null;
    creation = view.getUint32(off + 4, false);
    timescale = view.getUint32(off + 12, false);
    duration = view.getUint32(off + 16, false);
  }

  if (timescale <= 0) return null;

  return {
    creationUtcMs: (creation - EPOCH_OFFSET_1904_TO_1970) * 1000,
    durationSeconds: duration / timescale,
  };
}
