import { findAllMarkers, parseMovieHeader } from './mp4-atoms.js';

const RECORD_SIZE = 1008;
const TIMESTAMP_OFFSET = 18;
const TIMESTAMP_SIZE = 14;       // "YYYYMMDDHHmmss"
const GPS_DATA_OFFSET = 48;
const GPS_DATA_SIZE = 27;
const XOR_KEY = 0xAA;

const ALL_ZEROS_GPS = '0'.repeat(GPS_DATA_SIZE);
const decoder = new TextDecoder('ascii');

/**
 * Parse all GPS records from an Azdome M300S MP4 ArrayBuffer.
 * Returns { samples: Array<{t, lat, lon, speed, heading}> } sorted by t.
 *
 * Records are 1008 bytes, located by the 4-byte ASCII magic 'GPS '.
 * Bytes from offset +12 are XOR-encoded with 0xAA. GPS coordinates
 * are stored as ASCII in NMEA-like DDMM.MMMM format. There is no
 * heading field in the source — heading is computed from successive
 * positions (initial bearing on a great circle).
 *
 * Records with the all-zeros GPS field (no fix) are dropped.
 *
 * @param {ArrayBuffer} arrayBuffer
 * @param {(p: number) => void} [onProgress] called with values in [0, 1]
 */
export function parseGpsTrack(arrayBuffer, onProgress) {
  const offsets = findAllMarkers(arrayBuffer, 'GPS ');
  if (onProgress) onProgress(0.5);

  const records = [];
  for (let i = 0; i < offsets.length; i++) {
    const off = offsets[i];
    if (off + RECORD_SIZE > arrayBuffer.byteLength) continue;

    const decoded = xorDecodeRegion(arrayBuffer, off + 12, RECORD_SIZE - 12);
    const tsRaw = readAscii(decoded, TIMESTAMP_OFFSET - 12, TIMESTAMP_SIZE);
    const gpsRaw = readAscii(decoded, GPS_DATA_OFFSET - 12, GPS_DATA_SIZE);

    if (gpsRaw === ALL_ZEROS_GPS) continue;

    const utc = parseTimestamp(tsRaw);
    if (utc === null) continue;

    const parsed = parseGpsField(gpsRaw);
    if (parsed === null) continue;

    records.push({ utc, ...parsed });

    if (onProgress && (i & 31) === 0) {
      onProgress(0.5 + 0.5 * (i / offsets.length));
    }
  }

  records.sort((a, b) => a.utc - b.utc);

  if (records.length === 0) return { samples: [] };

  const { startMs, durationS } = pickRecordingStart(arrayBuffer, records);

  // First, compute samples without heading (heading is filled in next).
  // Drop samples outside [0, durationS] — these are clock-skew artefacts.
  const samples = records
    .map(r => ({
      t: (r.utc - startMs) / 1000,
      lat: r.lat,
      lon: r.lon,
      speed: r.speed,
      heading: 0,
    }))
    .filter(s => s.t >= 0 && s.t <= durationS);

  // Synthesize heading from successive positions.
  for (let i = 0; i < samples.length - 1; i++) {
    samples[i].heading = bearing(samples[i], samples[i + 1]);
  }
  if (samples.length >= 2) {
    samples[samples.length - 1].heading = samples[samples.length - 2].heading;
  }

  if (onProgress) onProgress(1);
  return { samples };
}

/**
 * Determine the video's recording-start UTC (in ms) so each GPS sample's
 * `t = (gps_utc - startMs) / 1000` aligns with the video timeline.
 *
 * Strategy:
 *   1. Read mvhd (creation_time, duration). If absent, fall back to legacy
 *      "anchor at first GPS record" with no duration cap.
 *   2. Two candidate anchors:
 *      A: mvhd.creation_time           (firmware writes recording start)
 *      B: mvhd.creation_time - duration (firmware writes file-finalize time)
 *      Azdome M300S uses B; some other firmware uses A.
 *   3. Pick whichever places ALL records in [0, duration + tolerance].
 *      If both qualify, prefer B (matches the device we have evidence for).
 *      If neither qualifies, fall back to legacy.
 */
function pickRecordingStart(arrayBuffer, records) {
  const movie = parseMovieHeader(arrayBuffer);
  if (!movie) {
    return { startMs: records[0].utc, durationS: Infinity };
  }
  const firstUtc = records[0].utc;
  const lastUtc  = records[records.length - 1].utc;
  const TOL = 5; // seconds — clock skew tolerance
  const fits = (startMs) => {
    const first = (firstUtc - startMs) / 1000;
    const last  = (lastUtc  - startMs) / 1000;
    return first >= -TOL && last <= movie.durationSeconds + TOL;
  };

  const candidateB = movie.creationUtcMs - movie.durationSeconds * 1000;
  const candidateA = movie.creationUtcMs;

  if (fits(candidateB)) return { startMs: candidateB, durationS: movie.durationSeconds };
  if (fits(candidateA)) return { startMs: candidateA, durationS: movie.durationSeconds };
  return { startMs: firstUtc, durationS: Infinity };
}

function xorDecodeRegion(buf, start, length) {
  const src = new Uint8Array(buf, start, length);
  const out = new Uint8Array(length);
  for (let i = 0; i < length; i++) out[i] = src[i] ^ XOR_KEY;
  return out;
}

function readAscii(buf, start, length) {
  return decoder.decode(buf.subarray(start, start + length));
}

function parseTimestamp(s) {
  // YYYYMMDDHHmmss — every char must be a digit
  if (!/^\d{14}$/.test(s)) return null;
  const Y = +s.slice(0, 4);
  const M = +s.slice(4, 6);
  const D = +s.slice(6, 8);
  const h = +s.slice(8, 10);
  const m = +s.slice(10, 12);
  const sec = +s.slice(12, 14);
  if (M < 1 || M > 12 || D < 1 || D > 31) return null;
  return Date.UTC(Y, M - 1, D, h, m, sec);
}

function parseGpsField(s) {
  // 1 + 8 + 1 + 9 + 8 = 27 chars
  // [N|S][DDMMmmmm][E|W][DDDMMmmmm][SSSSSSSS]
  if (s.length !== GPS_DATA_SIZE) return null;
  const hemiLat = s[0];
  const latStr = s.slice(1, 9);
  const hemiLon = s[9];
  const lonStr = s.slice(10, 19);
  const speedStr = s.slice(19, 27);

  if (hemiLat !== 'N' && hemiLat !== 'S') return null;
  if (hemiLon !== 'E' && hemiLon !== 'W') return null;
  if (!/^\d{8}$/.test(latStr)) return null;
  if (!/^\d{9}$/.test(lonStr)) return null;
  if (!/^\d{8}$/.test(speedStr)) return null;

  // lat: DDMMmmmm → degrees (2) + decimal minutes (6)
  // e.g. "44513559" → deg=44, min=51.3559 → 44 + 51.3559/60
  const latDeg = +latStr.slice(0, 2);
  const latMin = parseFloat(latStr.slice(2, 4) + '.' + latStr.slice(4));
  let lat = latDeg + latMin / 60;
  if (hemiLat === 'S') lat = -lat;

  // lon: DDDMMmmmm → degrees (3) + decimal minutes (6)
  // e.g. "000307954" → deg=0, min=30.7954 → 0 + 30.7954/60
  const lonDeg = +lonStr.slice(0, 3);
  const lonMin = parseFloat(lonStr.slice(3, 5) + '.' + lonStr.slice(5));
  let lon = lonDeg + lonMin / 60;
  if (hemiLon === 'W') lon = -lon;

  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
  if (Math.abs(lat) > 90 || Math.abs(lon) > 180) return null;

  const speed = +speedStr;

  return { lat, lon, speed };
}

/**
 * Initial bearing on a great circle from `a` to `b`, in degrees [0, 360).
 * Standard "forward azimuth" formula.
 */
function bearing(a, b) {
  const φ1 = (a.lat * Math.PI) / 180;
  const φ2 = (b.lat * Math.PI) / 180;
  const Δλ = ((b.lon - a.lon) * Math.PI) / 180;
  const y = Math.sin(Δλ) * Math.cos(φ2);
  const x =
    Math.cos(φ1) * Math.sin(φ2) - Math.sin(φ1) * Math.cos(φ2) * Math.cos(Δλ);
  const θ = Math.atan2(y, x);
  const deg = (θ * 180) / Math.PI;
  return (deg + 360) % 360;
}
